CREATE TABLE IF NOT EXISTS gis_phase384_verification (id BIGSERIAL PRIMARY KEY, verified_at TIMESTAMPTZ NOT NULL DEFAULT now(), source_count BIGINT NOT NULL, stored_count BIGINT NOT NULL, missing_count BIGINT NOT NULL, invalid_geometry_count BIGINT NOT NULL, duplicate_count BIGINT NOT NULL, ingestion_complete BOOLEAN NOT NULL, source_complete BOOLEAN NOT NULL, geometry_complete BOOLEAN NOT NULL, ready_for_certification BOOLEAN NOT NULL);